class DemoSeeder extends Seeder{public function run():void{$registered=Role::firstOrCreate(['name'=>'REGISTERED_USER']);$providerRole=Role::firstOrCreate(['name'=>'PROVIDER']);$adminRole=Role::firstOrCreate(['name'=>'ADMIN']);$customer=User::updateOrCreate(['phone'=>'+201000000001'],['name'=>'Demo Customer','email'=>'customer@blackhorse.test','password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$admin=User::updateOrCreate(['phone'=>'+201000000002'],['name'=>'Demo Admin','email'=>'admin@blackhorse.test','password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$provUser=User::updateOrCreate(['phone'=>'+201000000003'],['name'=>'Captain Ahmed Farouk','email'=>'provider@blackhorse.test','password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$customer->roles()->syncWithoutDetaching([$registered->id]);$admin->roles()->syncWithoutDetaching([$adminRole->id]);$provUser->roles()->syncWithoutDetaching([$registered->id,$providerRole->id]);$pc=ProviderCategory::firstOrCreate(['name'=>'Trainer'],['status'=>'ACTIVE']);Provider::updateOrCreate(['user_id'=>$provUser->id],['category_id'=>$pc->id,'bio'=>'Certified dressage and rehabilitation specialist with 15 years of experience.','experience_years'=>15,'location'=>'Cairo','verification_status'=>'VERIFIED','approved_at'=>now()]);$sc=ServiceCategory::firstOrCreate(['name'=>'Horse Training'],['status'=>'ACTIVE']);foreach([['Horse Training','Individual training programs for performance and partnership.'],['Rehabilitation','Structured recovery plans guided by experienced professionals.'],['Consulting','Practical advice for owners, stables, and equestrian projects.'],['Horse Care','Premium daily care and wellbeing support.']] as [$title,$desc])Service::firstOrCreate(['title'=>$title],['category_id'=>$sc->id,'short_description'=>$desc,'description'=>$desc,'status'=>'ACTIVE','created_by'=>$admin->id]);$poc=PortfolioCategory::firstOrCreate(['name'=>'Training Success'],['status'=>'ACTIVE']);$item=PortfolioItem::firstOrCreate(['title'=>'A stronger partnership'],['category_id'=>$poc->id,'short_description'=>'A success story in confidence and performance.','description'=>'A tailored program helped horse and rider build trust, balance, and consistency.','status'=>'ACTIVE','created_by'=>$admin->id]);$service=Service::where('title','Horse Training')->first();$req=LeadRequest::firstOrCreate(['phone'=>$customer->phone,'message'=>'I would like to discuss a training program.'],['user_id'=>$customer->id,'service_id'=>$service->id,'name'=>$customer->name,'status'=>'IN_PROGRESS']);RequestAssignment::firstOrCreate(['request_id'=>$req->id],['admin_id'=>$admin->id,'assigned_at'=>now(),'status'=>'ASSIGNED','notes'=>'Demo follow-up']);Notification::firstOrCreate(['user_id'=>$customer->id,'type'=>'REQUEST_STATUS_CHANGED'],['title'=>'Request update','message'=>'Your training request is now in progress.','data'=>['request_id'=>$req->id]]);Notification::firstOrCreate(['user_id'=>$provUser->id,'type'=>'PROVIDER_APPLICATION_APPROVED'],['title'=>'Provider profile verified','message'=>'Your Black Horse provider profile is now public.']);}}
